#!/bin/sh
set -eu

# The JVM distribution: bin/jreleaser (a POSIX sh launcher generated by
# JReleaser itself) plus lib/*.jar, run with `-classpath lib/* org.jreleaser.cli.Main`.
# One artifact for both arches.
unzip -q "jreleaser-${MINIMAL_ARG_VERSION}.zip"
SRC="jreleaser-${MINIMAL_ARG_VERSION}"

INSTALL="$OUTPUT_DIR/usr/share/jreleaser"
mkdir -p "$OUTPUT_DIR/usr/bin" "$INSTALL/bin" "$INSTALL/lib"
# The zip stores the jars as 0600; install with explicit modes.
install -m 0755 "$SRC/bin/jreleaser" "$INSTALL/bin/jreleaser"
for jar in "$SRC"/lib/*.jar; do
  install -m 0644 "$jar" "$INSTALL/lib/"
done
install -m 0644 "$SRC/LICENSE" "$SRC/NOTICE" "$INSTALL/"

# Wrapper. The upstream launcher resolves APP_HOME from its own path, uses
# $JAVA_HOME/bin/java if JAVA_HOME is set and `java` on PATH otherwise (the
# packaged jdk provides both), and honours JAVA_OPTS.
cat > "$OUTPUT_DIR/usr/bin/jreleaser" << 'WRAPPER'
#!/bin/sh
exec /usr/share/jreleaser/bin/jreleaser "$@"
WRAPPER
chmod 0755 "$OUTPUT_DIR/usr/bin/jreleaser"

# Fail closed if the distribution layout changes.
test -s "$INSTALL/lib/jreleaser-${MINIMAL_ARG_VERSION}.jar"
